insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-much-deposit-do-i-pay-when-renting-in-dubai', 'How much deposit do I pay when renting in Dubai?', '<p>Most landlords require a security deposit of 5–10% of the annual rent, refundable at end of tenancy subject to property condition. Your <a href="/account/transactions">property applications</a> shows the exact deposit before you pay. See our <a href="/pages/renting-guide">Renting Guide</a> for a full cost breakdown.</p>', 'How much deposit do I pay when renting in Dubai?', 0, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-pay-rent-in-multiple-cheques-in-dubai', 'Can I pay rent in multiple cheques in Dubai?', '<p>Yes. Cheque plans vary by property — from one annual cheque to twelve monthly post-dated cheques. Each listing displays the available plan. Browse <a href="/collection/rentals">holiday and long-term rentals</a> and filter by payment terms, or <a href="/pages/contact">contact our team</a> for custom arrangements.</p>', 'Can I pay rent in multiple cheques in Dubai?', 1, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-ejari-and-do-i-need-it-for-my-rental', 'What is Ejari and do I need it for my rental?', '<p>Ejari is Dubai''s official tenancy registration with RERA. It protects both tenant and landlord and is required for DEWA connection and visa processes. We coordinate Ejari as part of move-in — details in <a href="/pages/shipping">Handover Information</a> and <a href="/pages/renting-guide">Renting Guide</a>.</p>', 'What is Ejari and do I need it for my rental?', 2, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-long-is-a-standard-dubai-tenancy-contract', 'How long is a standard Dubai tenancy contract?', '<p>Most residential leases run 12 months. Some short-term <a href="/collection/rentals">holiday and long-term rentals</a> may offer 3–6 month terms. Contract duration is confirmed in your <a href="/account/transactions">property applications</a> before signing.</p>', 'How long is a standard Dubai tenancy contract?', 3, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-tourists-rent-a-property-in-dubai', 'Can tourists rent a property in Dubai?', '<p>Yes, many vacation and furnished rentals accept tourist visas with valid passport copies. Long-term leases typically require Emirates ID or a valid UAE visa. Submit an inquiry on any listing or use <a href="/search">property search</a> to find furnished options.</p>', 'Can tourists rent a property in Dubai?', 4, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-documents-do-i-need-to-rent-an-apartment-in-dubai', 'What documents do I need to rent an apartment in Dubai?', '<p>Usually: passport, UAE visa/Emirates ID, salary certificate or bank statements, and sometimes a security cheque. Upload details to <a href="/account/profile">My Profile</a> so your agent can prepare the contract faster.</p>', 'What documents do I need to rent an apartment in Dubai?', 5, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'is-agency-commission-charged-on-rentals-in-dubai', 'Is agency commission charged on rentals in Dubai?', '<p>Yes — typically 5% of annual rent plus VAT, paid once at contract signing. Commission is itemised in your payment breakdown inside <a href="/account/transactions">property applications</a>. Compare <a href="/collection/new">new listings</a> listings for transparent fee disclosure.</p>', 'Is agency commission charged on rentals in Dubai?', 6, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-negotiate-rent-on-a-dubai-property-listing', 'Can I negotiate rent on a Dubai property listing?', '<p>Negotiation depends on the owner and market conditions. Submit an inquiry through the listing; your agent will advise on realistic offers. Explore <a href="/collection/all">all listings</a> to compare similar units in the same area.</p>', 'Can I negotiate rent on a Dubai property listing?', 7, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-rera-and-how-does-it-protect-tenants', 'What is RERA and how does it protect tenants?', '<p>The Real Estate Regulatory Agency (RERA) regulates brokers, contracts, and escrow. GW Vacation Homes operates under RERA guidelines. Learn more on our <a href="/pages/about">About GW Vacation Homes</a> page and <a href="/pages/terms">Terms of Service</a>.</p>', 'What is RERA and how does it protect tenants?', 8, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-sublet-my-rental-property-in-dubai', 'Can I sublet my rental property in Dubai?', '<p>Subletting requires explicit written consent from the landlord. Unauthorized subletting can void your tenancy. Check your contract terms in <a href="/account/transactions">property applications</a> or ask via <a href="/pages/contact">contact our team</a>.</p>', 'Can I sublet my rental property in Dubai?', 9, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-happens-if-a-rent-cheque-bounces-in-dubai', 'What happens if a rent cheque bounces in Dubai?', '<p>Bounced cheques are a serious offence in the UAE and can lead to legal action. Ensure sufficient funds before issuing post-dated cheques. Your <a href="/pages/renting-guide">Renting Guide</a> explains cheque best practices.</p>', 'What happens if a rent cheque bounces in Dubai?', 10, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'are-utilities-included-in-dubai-rent', 'Are utilities included in Dubai rent?', '<p>Most long-term leases exclude DEWA (electricity/water) and district cooling (chiller). Short-term <a href="/collection/rentals">holiday and long-term rentals</a> may include utilities — check each listing. See Ejari and DEWA FAQs in this help centre.</p>', 'Are utilities included in Dubai rent?', 11, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-i-break-a-tenancy-contract-early-in-dubai', 'Can I break a tenancy contract early in Dubai?', '<p>Early termination clauses vary. Some contracts require 1–3 months'' notice and penalty fees. Review terms before signing; your agent explains options in <a href="/account/transactions">property applications</a>.</p>', 'Can I break a tenancy contract early in Dubai?', 12, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'do-i-need-home-insurance-as-a-tenant-in-dubai', 'Do I need home insurance as a tenant in Dubai?', '<p>Contents insurance is recommended but not always mandatory. Building insurance is typically the landlord''s responsibility. <a href="/pages/contact">contact our team</a> for partner referrals if needed.</p>', 'Do I need home insurance as a tenant in Dubai?', 13, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'what-is-a-fit-out-or-furnishing-clause-in-a-lease', 'What is a fit-out or furnishing clause in a lease?', '<p>It defines whether the unit is unfurnished, semi-furnished, or fully furnished. Listings show furnishing type on each property page. Browse <a href="/collection/rentals">holiday and long-term rentals</a> and filter by preference.</p>', 'What is a fit-out or furnishing clause in a lease?', 14, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'how-do-i-renew-my-tenancy-in-dubai', 'How do I renew my tenancy in Dubai?', '<p>Renewals usually start 90 days before expiry. Your agent contacts you via <a href="/account">My Account</a> notifications. Updated terms and rent adjustments are shared before re-signing.</p>', 'How do I renew my tenancy in Dubai?', 15, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
insert into public.faqs (category_id, slug, question, answer_html, meta_description, sort_order, is_published) select id, 'can-two-people-share-a-tenancy-contract-in-dubai', 'Can two people share a tenancy contract in Dubai?', '<p>Yes — joint tenancy is common. All tenants should be named on the Ejari contract. Add co-tenant details in <a href="/account/profile">My Profile</a> when applying.</p>', 'Can two people share a tenancy contract in Dubai?', 16, true from public.faq_categories where slug = 'renting-dubai' on conflict (slug) do update set question = excluded.question, answer_html = excluded.answer_html, meta_description = excluded.meta_description, sort_order = excluded.sort_order, updated_at = now();
